import { Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import TruncatedText from '../TruncatedText'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import * as uploadQueue from './uploadQueue'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const settled = uploadQueue.hasSettled(flattenFiles(tree).map(f => f.path))

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} groupKey={group.name} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button variant="default" disabled={settled} onClick={() => uploadQueue.cancelRemaining()}>
            Cancel remaining
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group, groupKey }: { group: LocalFileGroup; groupKey: string }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} groupKey={`${groupKey}/${sub.name}`} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status ?? 'idle'

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.cancel(file.path)}>
            Cancel
          </Button>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {status === 'idle' && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
    </Group>
  )
}

import { useEffect, useState } from 'react'
import { CancelUpload, UploadFile } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'

export type UploadStatus = 'idle' | 'queued' | 'uploading' | 'done' | 'error' | 'cancelled'

export interface UploadJob {
  path: string
  folderId: string
  name: string
}

export interface UploadEntry extends UploadJob {
  status: UploadStatus
  error?: string
}

// Per-file upload status, driven by a sequential (concurrency = 1) worker.
// A module-level singleton (like ../../lib/pageCache) rather than a hook:
// there is only ever one upload run in flight for the app, so the queue's
// lifetime doesn't need to be tied to any one component instance. Callers
// resolve each file's destination folder/name up front and pass in an
// ordered list of jobs — this module only knows how to run them one at a
// time and track status, not about the file tree or Drive assignments.
const filesByPath = new Map<string, UploadEntry>()
let pendingPaths: string[] = []
const listeners = new Set<() => void>()
let running = false
let cancelled = false

// Paths whose in-flight upload was cancelled. runQueue checks this once the
// awaited UploadFile call settles (success or failure) and, if present,
// leaves the status as 'cancelled' instead of overwriting it with
// 'done'/'error' — the request may have raced ahead of the abort signal, but
// the user's intent to cancel wins either way.
const cancelledInFlight = new Set<string>()

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

export function useUploadQueueRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getStatus(path: string): UploadEntry | undefined {
  return filesByPath.get(path)
}

// True once none of the given files are still queued or uploading — i.e.
// each has either reached a terminal state (done/error) or was never
// started. Callers use this to know when it's safe to let the upload
// modal close.
export function hasSettled(paths: string[]): boolean {
  return !paths.some(path => {
    const status = filesByPath.get(path)?.status
    return status === 'queued' || status === 'uploading'
  })
}

function updateStatus(path: string, status: UploadStatus, error?: string) {
  const existing = filesByPath.get(path)!
  filesByPath.set(path, { ...existing, status, error })
  notify()
}

async function runQueue() {
  if (running) return
  running = true
  while (!cancelled && pendingPaths.length > 0) {
    const path = pendingPaths.shift()!
    const job = filesByPath.get(path)!
    updateStatus(path, 'uploading')
    try {
      await UploadFile(job.path, job.folderId, job.name)
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'done')
    } catch (e) {
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'error', String(e))
    }
  }
  running = false
}

function enqueue(newJobs: UploadJob[]) {
  if (newJobs.length === 0) return
  cancelled = false
  for (const job of newJobs) {
    filesByPath.set(job.path, { ...job, status: 'queued', error: undefined })
    pendingPaths.push(job.path)
  }
  notify()
  void runQueue()
}

export function start(newJobs: UploadJob[]): void {
  enqueue(newJobs)
}

export function retry(job: UploadJob): void {
  enqueue([job])
}

// Stops starting new files; does not abort an in-flight request. Files
// still waiting their turn go back to idle since they were never attempted.
export function cancelRemaining(): void {
  cancelled = true
  for (const path of pendingPaths) updateStatus(path, 'idle')
  pendingPaths = []
}

// Aborts the file currently uploading. A no-op for any other status —
// queued files are handled by cancelRemaining, and done/error/cancelled are
// already settled. Marks the file 'cancelled' immediately rather than
// waiting on the CancelUpload round-trip or on however UploadFile's promise
// ends up settling.
export function cancel(path: string): void {
  if (filesByPath.get(path)?.status !== 'uploading') return
  cancelledInFlight.add(path)
  updateStatus(path, 'cancelled')
  CancelUpload(path).catch(handlePromiseRejection('Canceling upload failed'))
}

export function reset(): void {
  if (!hasSettled(Array.from(filesByPath.keys()))) {
    // Callers must only invoke this once hasSettled() is true for all files;
    // otherwise a request from the discarded run could still be in flight and
    // would resurface after this call.
    throw new Error('reset() called while an upload is still in flight')
  }
  cancelled = false
  running = false
  cancelledInFlight.clear()
  filesByPath.clear()
  pendingPaths = []
  notify()
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { waitFor } from '@testing-library/react'
import * as uploadQueue from './uploadQueue'
import { UploadJob } from './uploadQueue'
import { CancelUpload, UploadFile } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  UploadFile: vi.fn(),
  CancelUpload: vi.fn(),
}))

function deferred<T>() {
  let resolve!: (v: T) => void
  let reject!: (e: unknown) => void
  const promise = new Promise<T>((res, rej) => { resolve = res; reject = rej })
  return { promise, resolve, reject }
}

const jobA: UploadJob = { path: '/root/a.pdf', folderId: 'f1', name: 'a.pdf' }
const jobB: UploadJob = { path: '/root/b.pdf', folderId: 'f1', name: 'b.pdf' }

describe('uploadQueue', () => {
  beforeEach(() => {
    vi.mocked(UploadFile).mockReset()
    vi.mocked(CancelUpload).mockReset().mockResolvedValue(undefined)
    uploadQueue.reset()
  })

  it('starts with no status for a file', () => {
    expect(uploadQueue.getStatus(jobA.path)).toBeUndefined()
  })

  it('runs jobs sequentially, one uploading at a time', async () => {
    const first = deferred<string>()
    const second = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    uploadQueue.start([jobA, jobB])

    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('uploading')
    expect(uploadQueue.getStatus(jobB.path)?.status).toBe('queued')
    expect(UploadFile).toHaveBeenCalledTimes(1)

    first.resolve('id-a')
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
    await waitFor(() => expect(uploadQueue.getStatus(jobB.path)?.status).toBe('uploading'))
    expect(UploadFile).toHaveBeenCalledTimes(2)

    second.resolve('id-b')
    await waitFor(() => expect(uploadQueue.getStatus(jobB.path)?.status).toBe('done'))
  })

  it('marks a failed upload as error with a message', async () => {
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('quota exceeded'))

    uploadQueue.start([jobA])

    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('error'))
    expect(uploadQueue.getStatus(jobA.path)?.error).toContain('quota exceeded')
  })

  it('retry re-queues just that file', async () => {
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('fail'))
    uploadQueue.start([jobA])
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('error'))

    vi.mocked(UploadFile).mockResolvedValueOnce('id-a')
    uploadQueue.retry(jobA)

    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
    expect(UploadFile).toHaveBeenCalledTimes(2)
  })

  it('retry clears the previous error, even when passed the stale UploadEntry itself', async () => {
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('fail'))
    uploadQueue.start([jobA])
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('error'))

    // Realistic call site: a Retry button passes the UploadEntry it already has
    // from getStatus(), not a hand-trimmed UploadJob — it still carries the old
    // status/error fields, which retry() must not let leak into the requeue.
    const staleEntry = uploadQueue.getStatus(jobA.path)!

    // Keep the worker busy on jobB so jobA's requeue is left sitting in
    // 'queued' rather than immediately promoted to 'uploading' (which would
    // clear .error on its own and hide the bug this test is checking for).
    const busy = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(busy.promise)
    uploadQueue.start([jobB])
    uploadQueue.retry(staleEntry)

    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('queued')
    expect(uploadQueue.getStatus(jobA.path)?.error).toBeUndefined()

    // Let the queue drain so it doesn't leave a dangling promise behind
    // (mockReset() in the next beforeEach can't unstick an in-flight loop).
    busy.resolve('id-b')
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
  })

  it('cancelRemaining stops starting new files and reverts queued files to idle', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    uploadQueue.start([jobA, jobB])
    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('uploading')

    uploadQueue.cancelRemaining()
    expect(uploadQueue.getStatus(jobB.path)?.status).toBe('idle')

    first.resolve('id-a')
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
    expect(UploadFile).toHaveBeenCalledTimes(1)
  })

  it('cancel marks the uploading file cancelled and calls the backend', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
    uploadQueue.start([jobA])

    uploadQueue.cancel(jobA.path)
    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('cancelled')
    expect(CancelUpload).toHaveBeenCalledWith(jobA.path)

    // Let the queue drain so it doesn't leave a dangling promise behind.
    first.resolve('id-a')
    await waitFor(() => expect(UploadFile).toHaveBeenCalledTimes(1))
  })

  it('cancel is ignored for a file that is not currently uploading', () => {
    uploadQueue.start([jobA, jobB]) // jobA uploading, jobB queued

    uploadQueue.cancel(jobB.path)
    expect(uploadQueue.getStatus(jobB.path)?.status).toBe('queued')
    expect(CancelUpload).not.toHaveBeenCalled()
  })

  it('cancelling in flight leaves status as cancelled even if the upload later resolves successfully', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
    uploadQueue.start([jobA])

    uploadQueue.cancel(jobA.path)
    first.resolve('id-a')

    // Give runQueue's continuation a turn; status must not flip to 'done'.
    await Promise.resolve()
    await Promise.resolve()
    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('cancelled')
  })

  it('cancelling in flight leaves status as cancelled rather than error if the upload rejects', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
    uploadQueue.start([jobA])

    uploadQueue.cancel(jobA.path)
    first.reject(new Error('aborted'))

    await Promise.resolve()
    await Promise.resolve()
    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('cancelled')
  })

  it('reset throws if a file is still queued or uploading', () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    uploadQueue.start([jobA])
    expect(uploadQueue.getStatus(jobA.path)?.status).toBe('uploading')

    expect(() => uploadQueue.reset()).toThrow()

    // Let the queue drain so it doesn't leave a dangling promise behind.
    first.resolve('id-a')
    return waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
  })

  it('reset clears all statuses once settled, and lets a new run start immediately', async () => {
    const first = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
    uploadQueue.start([jobA])

    first.resolve('id-a')
    await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))

    uploadQueue.reset()
    expect(uploadQueue.getStatus(jobA.path)).toBeUndefined()

    const second = deferred<string>()
    vi.mocked(UploadFile).mockReturnValueOnce(second.promise)
    uploadQueue.start([jobB])
    expect(uploadQueue.getStatus(jobB.path)?.status).toBe('uploading')

    // Let the queue drain so it doesn't leave a dangling promise behind.
    second.resolve('id-b')
    await waitFor(() => expect(uploadQueue.getStatus(jobB.path)?.status).toBe('done'))
  })

  describe('hasSettled', () => {
    it('is true for paths with no status at all', () => {
      expect(uploadQueue.hasSettled([jobA.path, jobB.path])).toBe(true)
    })

    it('is false while any given path is queued or uploading', async () => {
      const first = deferred<string>()
      vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
      uploadQueue.start([jobA, jobB])

      expect(uploadQueue.hasSettled([jobA.path, jobB.path])).toBe(false)

      first.resolve('id-a')
      await waitFor(() => expect(uploadQueue.getStatus(jobA.path)?.status).toBe('done'))
      expect(uploadQueue.hasSettled([jobA.path, jobB.path])).toBe(true)
    })

    it('only considers the given paths, ignoring other in-flight uploads', () => {
      const first = deferred<string>()
      vi.mocked(UploadFile).mockReturnValueOnce(first.promise)
      uploadQueue.start([jobA]) // jobA now uploading

      expect(uploadQueue.hasSettled(['/root/unrelated.pdf'])).toBe(true)
    })
  })
})

