export type UploadStatus =
  /** Enqueued, waiting for the worker to reach it. */
  | 'queued'
  /**
   * Was queued, then reverted here by cancelRemaining/cancelAll before the
   * worker reached it — never actually attempted. This is the only way a
   * stored entry gets this status; resumeIdle re-queues these in bulk. A
   * file that was never enqueued at all defaults to this same status in the
   * UI (see FileRow's `entry?.status ?? 'idle'`) without ever getting a real
   * entry here — see hasIdle for why that distinction is sound.
   */
  | 'idle'
  /** The worker is currently awaiting UploadFile for it. */
  | 'uploading'
  /** Terminal: UploadFile resolved. */
  | 'done'
  /** Terminal: UploadFile rejected; .error holds the message. Retry re-queues it. */
  | 'error'
  /** Terminal: aborted mid-upload via cancel/cancelAll. Retry re-queues it. */
  | 'cancelled'

